const lessons=[{"sentences":[{"speaker":"A","text":"Hello Mark, we need to schedule the routine maintenance for our printing machines next week.","position":1,"audioStartSeconds":0,"audioEndSeconds":5.726666666666667},{"speaker":"B","text":"That is a good idea because the main office printer has been making strange noises lately.","position":2,"audioStartSeconds":5.926666666666667,"audioEndSeconds":11.382708333333333},{"speaker":"A","text":"The technician suggested coming on Tuesday morning if that fits our department schedule.","position":3,"audioStartSeconds":11.582708333333333,"audioEndSeconds":17.111833333333333},{"speaker":"B","text":"Tuesday is quite busy for our team because we have a monthly audit meeting then.","position":4,"audioStartSeconds":17.311833333333333,"audioEndSeconds":22.170833333333334},{"speaker":"A","text":"Could we ask him to visit on Wednesday afternoon instead when the office is quieter?","position":5,"audioStartSeconds":22.370833333333334,"audioEndSeconds":27.306375},{"speaker":"B","text":"Wednesday afternoon works perfectly for me, so please send him an email confirmation.","position":6,"audioStartSeconds":27.506375,"audioEndSeconds":32.931625},{"speaker":"A","text":"I will message him right now before he finalizes his weekly appointment calendar.","position":7,"audioStartSeconds":33.131625,"audioEndSeconds":38.389375},{"speaker":"A","text":"Excuse me Sarah, security needs your help with granting access for the new delivery drivers.","role":"section-start","position":8,"audioStartSeconds":43.389375,"audioEndSeconds":49.458958333333335},{"speaker":"B","text":"I can update the visitor database this afternoon once I finish my inventory report.","position":9,"audioStartSeconds":49.65895833333333,"audioEndSeconds":55.25175},{"speaker":"A","text":"The guards mentioned they need the temporary parking passes printed by noon tomorrow.","position":10,"audioStartSeconds":55.45175,"audioEndSeconds":60.49041666666667},{"speaker":"B","text":"That means I should finish the inventory report earlier than planned today.","position":11,"audioStartSeconds":60.690416666666664,"audioEndSeconds":65.381125},{"speaker":"A","text":"Would you like me to handle the parking passes while you finish your inventory?","position":12,"audioStartSeconds":65.581125,"audioEndSeconds":69.98833333333333},{"speaker":"B","text":"That would be wonderful, and I will update the driver database immediately afterwards.","position":13,"audioStartSeconds":70.18833333333333,"audioEndSeconds":75.72175},{"speaker":"A","text":"I will walk down to the security desk now and collect the badge forms.","position":14,"audioStartSeconds":75.92175,"audioEndSeconds":80.64283333333333}],"questions":[{"prompt":"What equipment requires routine maintenance?","options":["The office computers.","The printing machines.","The kitchen appliances."],"answer":"B","evidenceSentence":1,"evidence":"schedule the routine maintenance for our printing machines","explanation":"Người nói A nhắc đến việc bảo trì máy in (printing machines)."},{"prompt":"Why is Tuesday morning unsuitable for the first conversation?","options":["There is an audit meeting.","The office will be closed.","The technician is unavailable."],"answer":"A","evidenceSentence":4,"evidence":"we have a monthly audit meeting then","explanation":"Thứ ba không phù hợp vì có cuộc họp kiểm toán hàng tháng (audit meeting)."},{"prompt":"When will the technician visit the office?","options":["Tuesday morning.","Wednesday afternoon.","Thursday morning."],"answer":"B","evidenceSentence":5,"evidence":"visit on Wednesday afternoon instead","explanation":"Lịch hẹn được đổi sang chiều thứ tư (Wednesday afternoon)."},{"prompt":"What task does Sarah need to finish first in the second conversation?","options":["Her inventory report.","The security badges.","The delivery schedule."],"answer":"A","evidenceSentence":9,"evidence":"once I finish my inventory report","explanation":"Sarah cần hoàn thành báo cáo kiểm kê (inventory report) trước."},{"prompt":"When are the temporary parking passes needed by security?","options":["By noon tomorrow.","By Friday evening.","By the end of today."],"answer":"A","evidenceSentence":10,"evidence":"printed by noon tomorrow","explanation":"Bảo vệ cần thẻ đỗ xe trước trưa ngày mai (noon tomorrow)."},{"prompt":"What will speaker A do next in the second conversation?","options":["Update the driver database.","Collect the badge forms.","Print the inventory lists."],"answer":"B","evidenceSentence":14,"evidence":"collect the badge forms","explanation":"Người nói A sẽ đi lấy các mẫu thẻ (badge forms) ở bàn bảo vệ."}]}];const cards=[...document.querySelectorAll('article')];let stopping=null,stoppingAudio=null;
    document.addEventListener('play',event=>{if(event.target.tagName!=='AUDIO')return;document.querySelectorAll('audio').forEach(a=>{if(a!==event.target)a.pause()})},true);
    document.querySelectorAll('[data-filter]').forEach(button=>button.onclick=()=>{let count=0;cards.forEach(c=>{c.hidden=button.dataset.filter!=='ALL'&&c.dataset.goal!==button.dataset.filter;if(!c.hidden)count++;else c.querySelector('audio').pause()});document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',b===button));document.querySelector('#filter-status').textContent='Đang hiển thị '+count+' bài.'});
    const normal=value=>value.trim().toLowerCase().replace(/\s+/g,' ');
    document.querySelectorAll('[data-check]').forEach(button=>button.onclick=()=>{const i=Number(button.dataset.check);let score=0;lessons[i].questions.forEach((q,n)=>{const value=normal(document.getElementById('answer-'+i+'-'+n).value);if([q.answer,...(q.accepted||[])].some(a=>normal(a)===value))score++});document.getElementById('result-'+i).textContent=score+'/'+lessons[i].questions.length+' câu đúng. Mở phần đáp án để xem giải thích.'});
    document.querySelectorAll('[data-segment]').forEach(button=>button.onclick=async()=>{if(stopping)stopping();const [i,n]=button.dataset.segment.split(',').map(Number),audio=cards[i].querySelector('audio'),s=lessons[i].sentences[n];audio.currentTime=s.audioStartSeconds;const stop=()=>{stopping=null;stoppingAudio=null;audio.removeEventListener('timeupdate',check);audio.pause()},check=()=>{if(audio.currentTime>=s.audioEndSeconds)stop()};stopping=stop;stoppingAudio=audio;audio.addEventListener('timeupdate',check);try{await audio.play()}catch(_){stop();document.getElementById('result-'+i).textContent='Không phát được audio. Hãy dùng nút tải WAV để nghe.'}});
    document.querySelectorAll('audio').forEach(audio=>audio.addEventListener('pause',()=>{if(audio.paused&&stoppingAudio===audio&&stopping)stopping()}));
const authStatus=document.querySelector('#auth-status');
async function initializeAudio(){
 try{
  const response=await fetch('/api/auth/me',{credentials:'same-origin'});
  if(response.status===401){authStatus.hidden=false;authStatus.innerHTML='Đăng nhập để nghe audio. <a href="/login?next=%2Fcatalog%3Fgoal%3DALL">Đăng nhập</a> rồi mở bài từ thư viện bằng nút “Nghe toàn bài & làm câu hỏi”.';return}
  if(!response.ok)throw Error('account');
  document.querySelectorAll('audio').forEach(audio=>{audio.src=audio.dataset.src;audio.preload='none';audio.hidden=false});
  document.querySelectorAll('[data-segment]').forEach(button=>button.disabled=false);
  document.querySelectorAll('a[download]').forEach(link=>link.hidden=false);
 }catch(_){authStatus.hidden=false;authStatus.textContent='Không kiểm tra được đăng nhập. Hãy tải lại trang để thử lại.'}
}
initializeAudio();
